css_snippet:
/* For body text, gentle positive spacing to improve readability */
p {
  letter-spacing: 0.01em; /* Adjust slightly based on font */
}

/* For headlines, often negative spacing to tighten large text */
h1 {
  letter-spacing: -0.03em; /* Tighten for visual impact */
}

/* For small text, might need a bit more spacing */
.caption {
  font-size: 0.8em;
  letter-spacing: 0.02em;
}
